import{_ as o,o as t,c as n,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"2018-JAN-03 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2018-JAN-03 :: Ceph Developer Monthly","date":"2018-01-04T00:00:00.000Z","updated":"2018-01-04T00:00:00.000Z","tags":["Ceph","Kubernetes","Rook","OSD","CephFS","Ceph存储后端","OpenStack"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-JAN-03_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2018/2018-JAN-03_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780459816000}'),r={name:"posts/2018/2018-JAN-03_-_-_Ceph_Developer_Monthly.md"};function s(p,e,i,C,a,g){return t(),n("div",null,[...e[0]||(e[0]=[l("<p><strong>会议时间</strong>： 2018年1月（具体日期未提及） <strong>会议地点</strong>： CPM（Ceph社区项目会议） <strong>参会人员</strong>： Sage、Quentin、Jason、Dan、Mark、Kenda等</p><p><strong>会议主题</strong>：</p><ul><li><strong>Ceph配置管理系统（mod）更新</strong>： 包括配置存储、解析、验证和展示等，支持多种配置获取方式，但当前未进行身份验证。</li><li><strong>Kubernetes集群部署Ceph（Rook项目）</strong>： Rook项目成为Ceph在Kubernetes集群中部署的首选工具，支持自动化集群部署、升级和运维等操作。</li><li><strong>Easy Clones功能改进</strong>： 简化RBD克隆和快照操作，通过OSD能力（caps）控制克隆和快照操作。</li><li><strong>Ceph OSD性能优化</strong>： 旨在提高Ceph在高速存储设备上的性能，包括重构OSD、使用异步框架等。</li><li><strong>Ceph存储后端（C Store）开发</strong>： 开发新的存储后端，支持高速存储设备，使用Seastar框架和SPDK库。</li><li><strong>OpenStack测试平台（Technology）使用</strong>： 用于测试OpenStack与Ceph的集成。</li></ul><p><strong>会议内容</strong>：</p><ul><li><strong>Ceph配置管理系统（mod）更新</strong>： 讨论了配置选项的敏感性、Ceph存储后端缓存策略等问题，并建议使用“C Store”或“C18 Store”作为新存储后端的命名。</li><li><strong>Kubernetes集群部署Ceph（Rook项目）</strong>： 讨论了Rook项目的自定义控制器、自动化集群部署、升级和运维等操作，并与Rook项目团队合作，确保其与Ceph Mimic版本同步发布。</li><li><strong>Easy Clones功能改进</strong>： 讨论了如何通过OSD能力（caps）控制克隆和快照操作，以及如何将快照移动到“已删除但仍有引用”的命名空间，以防止误删除。</li><li><strong>Ceph OSD性能优化</strong>： 讨论了使用C Star框架重构OSD、使用异步框架改进OSD性能，以及开发针对高速存储设备的新的对象存储后端。</li><li><strong>Ceph存储后端（C Store）开发</strong>： 讨论了C Store项目的开发进度，包括使用Seastar框架和SPDK库，以及提供日志结构化的存储格式。</li><li><strong>OpenStack测试平台（Technology）使用</strong>： 讨论了Technology平台在测试OpenStack与Ceph集成中的作用，以及如何使用该平台进行Ceph测试。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>完成配置管理功能的身份验证功能。</li><li>完成Rook项目的开发工作，并确保其与Ceph Mimic版本同步发布。</li><li>完成Easy Clones功能的开发工作。</li><li>完成Ceph OSD性能优化项目的开发工作。</li><li>开发Ceph存储后端（C Store）。</li><li>探索使用Technology平台进行Ceph测试。</li></ul><p><strong>其他事项</strong>：</p><ul><li>讨论了Ceph配置选项的敏感性、Ceph存储后端缓存策略等问题。</li><li>讨论了Ceph存储后端（C Store）的命名问题，建议使用“C Store”或“C18 Store”。</li><li>讨论了Ceph社区将继续努力改进Ceph的性能和功能，以满足用户的需求。</li></ul>",9)])])}const S=o(r,[["render",s]]);export{_ as __pageData,S as default};
